$pageTitle='Actividad';$basePath='../';$adminScripts=true;$adminActive='actividad';require_once __DIR__.'/../includes/auth.php';requireAdmin('../login.php','../usuario/index.php');require_once __DIR__.'/../includes/firebase-data.php';
$usersRaw=firebaseRead(fn(FirebaseReadService $f)=>$f->rtdb('usuarios'));$users=is_array($usersRaw)?$usersRaw:[];$orders=array_values(array_filter(firebaseRead(fn(FirebaseReadService $f)=>$f->collection('pedidos')), 'is_array'));$reservations=array_values(array_filter(firebaseRead(fn(FirebaseReadService $f)=>$f->collection('reservas')), 'is_array'));$messages=array_values(array_filter(firebaseRead(fn(FirebaseReadService $f)=>$f->collection('mensajes')), 'is_array'));$events=[];
foreach($orders as $o){$type=(strtolower((string)($o['tipoUsuario']??''))==='fisico'||strtolower((string)($o['origenPedido']??''))==='pulsador')?'venta_fisica':'pedido';$events[]=['date'=>$o['fechaCreacion']??null,'type'=>$type,'actor'=>$o['nombreUsuario']??$o['usuarioId']??'Sin actor','description'=>orderSummary($o).' · '.money($o['total']??null),'origin'=>orderOrigin($o)];}
foreach($reservations as $r)$events[]=['date'=>$r['fechaCreacion']??$r['fechaSolicitada']??null,'type'=>'reserva','actor'=>$r['nombreCliente']??$r['usuarioId']??'Sin actor','description'=>$r['detalle']??'Reserva CHICHEJ','origin'=>'Firestore'];
foreach($messages as $m)$events[]=['date'=>$m['fechaCreacion']??null,'type'=>($m['tipo']??'')==='promocion'?'promocion':'informativo','actor'=>$m['creadoPorNombre']??'Administración','description'=>$m['titulo']??'Publicación CHICHEJ','origin'=>'Firestore'];
foreach($users as $uid=>$u)if(is_array($u))$events[]=['date'=>$u['fechaRegistro']??null,'type'=>'registro_usuario','actor'=>$u['nombre']??$uid,'description'=>'Registro de usuario','origin'=>'RTDB'];
usort($events,fn($a,$b)=>(firebaseDate($b['date'])?->getTimestamp()??0)<=>(firebaseDate($a['date'])?->getTimestamp()??0));$now=new DateTimeImmutable('now',new DateTimeZone('America/La_Paz'));
require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/navbar.php';require __DIR__.'/../includes/admin-nav.php';
?>
<main id="contenido" class="admin-page"><section class="admin-head admin-head--with-nav"><div class="container"><div><span class="eyebrow eyebrow--light">Trazabilidad</span><h1>Actividad</h1><p>Eventos inferidos de registros existentes. No se crea auditoría nueva.</p></div><span class="status-pill <?=firebaseReadFailed()?'status-pill--idle':'status-pill--active'?>">● <?=firebaseReadFailed()?'No fue posible cargar los datos':'Solo lectura'?></span></div></section><section class="section section--cream"><div class="container"><div class="activity-tabs"><a class="is-active" href="#sistema">Actividad del sistema</a><a href="#auditoria">Auditoría administrativa</a></div><section id="sistema" class="admin-data" data-filter-scope><div class="admin-filterbar"><label class="admin-search">Buscar<input type="search" data-filter-search placeholder="Actor, descripción u origen…"></label><label>Tipo<select data-filter-key="type"><option value="">Todos</option><option value="pedido">Pedidos</option><option value="venta_fisica">Ventas físicas</option><option value="reserva">Reservas</option><option value="registro_usuario">Usuarios</option><option value="promocion">Promociones</option><option value="informativo">Informativos</option></select></label><label>Período<select data-filter-key="period"><option value="all">Todos</option><option value="today">Hoy</option><option value="7days">Últimos 7 días</option><option value="month">Este mes</option><option value="year">Este año</option></select></label><span data-filter-count><?=count($events)?> registros</span></div><div class="activity-list admin-scroll-list" tabindex="0"><?php foreach($events as $event):$date=firebaseDate($event['date'])?->setTimezone(new DateTimeZone('America/La_Paz'));$periods=['all'];if($date){if($date->format('Y-m-d')===$now->format('Y-m-d'))$periods[]='today';if($date>=$now->modify('-6 days')->setTime(0,0))$periods[]='7days';if($date->format('Y-m')===$now->format('Y-m'))$periods[]='month';if($date->format('Y')===$now->format('Y'))$periods[]='year';}?><article class="activity-row" data-filter-row data-search="<?=h(implode(' ',[$event['actor'],$event['description'],$event['origin'],$event['type']]))?>" data-type="<?=h($event['type'])?>" data-period="<?=h(implode('|',$periods))?>"><time><?=h($date?displayDate($date):'Sin fecha válida')?></time><span><?=h(str_replace('_',' ',$event['type']))?></span><div><strong><?=h($event['actor'])?></strong><p><?=h($event['description'])?></p></div><small><?=h($event['origin'])?></small></article><?php endforeach;?></div><p data-filter-empty hidden>No hay actividad para los filtros seleccionados.</p></section><section id="auditoria" class="audit-empty"><span>◎</span><h2>Sin registros administrativos todavía</h2><p>Esta sección mostrará acciones explícitas de administradores cuando exista una fuente de escritura segura.</p><code>adminUid · adminNombre · acción · módulo · entidadId · valorAnterior · valorNuevo · fechaHora · origenWeb</code></section></div></section></main>
